import stat


def _mode(mode):
    out = list(stat.filemode(mode))
    if mode & stat.S_ISUID: out[3] = 's' if mode & stat.S_IXUSR else 'S'
    if mode & stat.S_ISGID: out[6] = 's' if mode & stat.S_IXGRP else 'S'
    if mode & stat.S_ISVTX: out[9] = 't' if mode & stat.S_IXOTH else 'T'
    return ''.join(out)


def format_printf(fmt, path, st=None, depth=0, root=None):
    """Format one entry. `st` should be lstat() metadata when available."""
    if st is None:
        try: st = os.lstat(path)
        except OSError: return ''
    path = os.fspath(path)
    name = os.path.basename(path.rstrip(os.sep)) or os.sep
    parent = os.path.dirname(path.rstrip(os.sep)) or ('.' if not os.path.isabs(path) else os.sep)
    try: target = os.readlink(path)
    except OSError: target = ''
    try: followed = os.stat(path)
    except OSError: followed = None
    blocks = getattr(st, 'st_blocks', (st.st_size + 511) // 512)
    if root is None: root = path
    root = os.fspath(root)
    relative = os.path.relpath(path, root)
    if relative == '.': relative = ''
    def typ(mode):
        return ('d' if stat.S_ISDIR(mode) else 'f' if stat.S_ISREG(mode) else 'l' if stat.S_ISLNK(mode) else 'p' if stat.S_ISFIFO(mode) else 's' if stat.S_ISSOCK(mode) else 'b' if stat.S_ISBLK(mode) else 'c' if stat.S_ISCHR(mode) else '?')
    try: followed = os.stat(path)
    except OSError: followed = None
    physical = stat.S_ISREG(st.st_mode)
    fsname = _fstype(path)
    values = {
        'p': path, 'f': name, 'h': parent, 'H': root, 'P': relative,
        'd': str(depth), 'D': str(st.st_dev), 'i': str(st.st_ino),
        'n': str(st.st_nlink), 's': str(st.st_size), 'b': str(blocks),
        'k': str((blocks + 1) // 2), 'm': format(stat.S_IMODE(st.st_mode), 'o'),
        'M': _mode(st.st_mode), 'y': ('b' if stat.S_ISBLK(st.st_mode) else 'c' if stat.S_ISCHR(st.st_mode) else 'd' if stat.S_ISDIR(st.st_mode) else 'p' if stat.S_ISFIFO(st.st_mode) else 'f' if stat.S_ISREG(st.st_mode) else 'l' if stat.S_ISLNK(st.st_mode) else 's' if stat.S_ISSOCK(st.st_mode) else '?'),
        'Y': ('N' if followed is None else 'b' if stat.S_ISBLK(followed.st_mode) else 'c' if stat.S_ISCHR(followed.st_mode) else 'd' if stat.S_ISDIR(followed.st_mode) else 'p' if stat.S_ISFIFO(followed.st_mode) else 'f' if stat.S_ISREG(followed.st_mode) else 'l' if stat.S_ISLNK(followed.st_mode) else 's' if stat.S_ISSOCK(followed.st_mode) else '?'),
        'u': _name(pwd.getpwuid, st.st_uid),
        'g': _name(grp.getgrgid, st.st_gid), 'U': str(st.st_uid), 'G': str(st.st_gid),
        'l': target, 't': _date_ns(getattr(st, 'st_mtime_ns', int(st.st_mtime * 1e9)), 'ctime'),
        'a': _date_ns(getattr(st, 'st_atime_ns', int(st.st_atime * 1e9)), 'ctime'),
        'c': _date_ns(getattr(st, 'st_ctime_ns', int(st.st_ctime * 1e9)), 'ctime'),
        'y': typ(st.st_mode), 'Y': typ(followed.st_mode) if followed else 'N',
        'S': ('%.6g' % (st.st_blocks * 512 / st.st_size)) if physical and st.st_size else '1',
        'F': fsname,
    }
    birth_ns = _birth_ns(path)
    birth = getattr(st, 'st_birthtime', birth_ns / 1e9 if birth_ns is not None else st.st_mtime)
    birth_ns = getattr(st, 'st_birthtime_ns', birth_ns if birth_ns is not None else int(birth * 1e9))
    times = {'A': getattr(st, 'st_atime', 0), 'C': st.st_ctime,
             'T': st.st_mtime, 'B': birth, 'W': birth, 'w': birth,
             'a': getattr(st, 'st_atime', 0), 'c': st.st_ctime, 't': st.st_mtime}
    ns_times = {'A': getattr(st, 'st_atime_ns', int(times['A'] * 1e9)),
                'C': getattr(st, 'st_ctime_ns', int(times['C'] * 1e9)),
                'T': getattr(st, 'st_mtime_ns', int(times['T'] * 1e9)),
                'B': birth_ns, 'W': birth_ns, 'w': birth_ns,
                'a': getattr(st, 'st_atime_ns', int(times['a'] * 1e9)),
                'c': getattr(st, 'st_ctime_ns', int(times['c'] * 1e9)),
                't': getattr(st, 'st_mtime_ns', int(times['t'] * 1e9))}
    out=[]; i=0
    while i < len(fmt):
        c=fmt[i]
        if c == '\\' and i+1 < len(fmt):
            i += 1
            esc=fmt[i]
            if esc == 'c': break
            out.append({'a':'\a','b':'\b','f':'\f','n':'\n','r':'\r','t':'\t','v':'\v','\\':'\\'}.get(esc, '\\'+esc))
        elif c == '%':
            if i+1 < len(fmt) and fmt[i+1] == '%': out.append('%'); i+=1
            else:
                j=i+1
                while j < len(fmt) and fmt[j] in '-+ #0' or (j < len(fmt) and fmt[j].isdigit()): j+=1
                if j < len(fmt) and fmt[j] == '.':
                    j+=1
                    while j<len(fmt) and fmt[j].isdigit(): j+=1
                spec=fmt[j] if j<len(fmt) else ''
                if spec in values: val=values[spec]
                elif spec in times:
                    t=times[spec]
                    sub=fmt[j+1] if j+1<len(fmt) else ''
                    if sub == '@': val=_epoch_ns(ns_times[spec]); j+=1
                    elif sub == '+': val=_date_ns(ns_times[spec], '+'); j+=1
                    elif spec in ('w','a','c','t'): val=_date_ns(ns_times[spec], 'ctime')
                    elif sub and sub.isalpha():
                        val=_date_ns(ns_times[spec], sub); j+=1
                    else: val=_date_ns(ns_times[spec], 'ctime')
                else: val=''
                # Apply printf-like string width/precision when present.
                prefix=fmt[i+1:j]
                if prefix:
                    import re
                    m=re.fullmatch(r'([-+ #0]*)(\d*)(?:\.(\d+))?',prefix)
                    if m:
                        flags,width,prec=m.groups(); width=int(width or 0)
                        if prec is not None: val=val[:int(prec)]
                        pad='0' if '0' in flags and '-' not in flags else ' '
                        val=val.ljust(width,pad) if '-' in flags else val.rjust(width,pad)
                out.append(val); i=j
        else: out.append(c)
        i+=1
    return ''.join(out)


def validate_format(fmt):
    """Return the first unsupported printf directive, or None when valid."""
    values = set('pfhHPdDinsbkmM u g U G l y Y S F'.replace(' ', ''))
    times = set('ACTBWwact')
    i = 0
    while i < len(fmt):
        if fmt[i] != '%':
            i += 1
            continue
        if i + 1 < len(fmt) and fmt[i + 1] == '%':
            i += 2
            continue
        j = i + 1
        while j < len(fmt) and fmt[j] in '-+ #0': j += 1
        while j < len(fmt) and fmt[j].isdigit(): j += 1
        if j < len(fmt) and fmt[j] == '.':
            j += 1
            while j < len(fmt) and fmt[j].isdigit(): j += 1
        if j >= len(fmt): return fmt[i:]
        spec = fmt[j]
        if spec not in values and spec not in times:
            return fmt[i:j + 1]
        if spec in times and j + 1 < len(fmt) and fmt[j + 1] in '@+':
            j += 1
        elif spec in times and j + 1 < len(fmt) and fmt[j + 1].isalpha():
            j += 1
        i = j + 1
    return None


def _name(fn, value):
    try: return fn(value).pw_name if fn is pwd.getpwuid else fn(value).gr_name
    except KeyError: return str(value)


def _fstype(path):
    """Return the type of the mounted filesystem containing path on Linux."""
    target = os.path.realpath(path)
    best = ('', '')
    try:
        with open('/proc/self/mountinfo', encoding='utf-8') as mounts:
            for line in mounts:
                fields = line.rstrip('\n').split(' ')
                sep = fields.index('-')
                mount = fields[4].replace('\\040', ' ').replace('\\011', '\t').replace('\\134', '\\')
                if (target == mount or target.startswith(mount.rstrip('/') + '/')) and len(mount) > len(best[0]):
                    best = (mount, fields[sep + 1])
    except (OSError, ValueError, IndexError):
        pass
    return best[1]


def _birth_ns(path):
    """Read Linux statx birth time when available."""
    class Timestamp(ctypes.Structure):
        _fields_ = [('sec', ctypes.c_int64), ('nsec', ctypes.c_uint32),
                    ('reserved', ctypes.c_int32)]
    class Statx(ctypes.Structure):
        _fields_ = [
            ('mask', ctypes.c_uint32), ('blksize', ctypes.c_uint32),
            ('attributes', ctypes.c_uint64), ('nlink', ctypes.c_uint32),
            ('uid', ctypes.c_uint32), ('gid', ctypes.c_uint32),
            ('mode', ctypes.c_uint16), ('spare0', ctypes.c_uint16),
            ('ino', ctypes.c_uint64), ('size', ctypes.c_uint64),
            ('blocks', ctypes.c_uint64), ('attributes_mask', ctypes.c_uint64),
            ('atime', Timestamp), ('btime', Timestamp),
            ('ctime', Timestamp), ('mtime', Timestamp),
            ('rdev_major', ctypes.c_uint32), ('rdev_minor', ctypes.c_uint32),
            ('dev_major', ctypes.c_uint32), ('dev_minor', ctypes.c_uint32),
            ('mnt_id', ctypes.c_uint64), ('dio_mem_align', ctypes.c_uint32),
            ('dio_offset_align', ctypes.c_uint32), ('spare', ctypes.c_uint64 * 12),
        ]
    try:
        libc = ctypes.CDLL(None, use_errno=True)
        fn = libc.statx
        fn.argtypes = [ctypes.c_int, ctypes.c_char_p, ctypes.c_int,
                       ctypes.c_uint, ctypes.POINTER(Statx)]
        fn.restype = ctypes.c_int
        result = Statx()
        raw = os.fsencode(path)
        if fn(-100, raw, 0, 0x800, ctypes.byref(result)) == 0 and result.mask & 0x800:
            return result.btime.sec * 1_000_000_000 + result.btime.nsec
    except (AttributeError, OSError, TypeError, ValueError):
        pass
    return None


def _epoch_ns(ns):
    sec, frac = divmod(ns, 1_000_000_000)
    return '%d.%010d' % (sec, frac * 10)


def _date_ns(ns, style):
    try:
        sec, frac = divmod(ns, 1_000_000_000)
        d=datetime.datetime.fromtimestamp(sec).astimezone()
        if style == '+': return d.strftime('%Y-%m-%d+%H:%M:%S') + ('.%010d' % (frac * 10))
        if style == 'ctime': return d.strftime('%a %b %e %H:%M:%S.') + ('%010d' % (frac * 10)) + d.strftime(' %Y')
        if style == 'a': style = '%a %b %d %H:%M:%S %Y'
        elif style == 'b': style = '%b'
        elif style == 'c': style = '%a %b %e %H:%M:%S %Y'
        elif style == 'r': style = '%I:%M:%S %p'
        elif style == 'x': style = '%m/%d/%y'
        elif style == 'X': style = '%H:%M:%S'
        elif style == 'y': style = '%y'
        elif style == 'z': style = '%z'
        elif style == 'Z': style = '%Z'
        else: style = '%' + style
        return d.strftime(style)
    except (OverflowError, OSError, ValueError): return ''

